private async Task SubmitButton_Click(object sender, EventArgs e)
{
    var order = await _orders.LoadAsync(OrderId);
    MessageBox.Show(order.Total.ToString("C"));
}

private async void SubmitButton_Click(object sender, EventArgs e)
{
    SubmitButton.Enabled = false;
    using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(10));
    try
    {
        var order = await _orders.LoadAsync(OrderId, cts.Token);
        MessageBox.Show(order.Total.ToString("C"));
    }
    catch (Exception ex)
    {
        _logger.LogError(ex, "click failed");
    }
    finally
    {
        SubmitButton.Enabled = true;
    }
}
